import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"PRD-030 · /explore v2 — The Known Universe","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-030.md","filePath":"prd/PRD-030.md"}'),s={name:"prd/PRD-030.md"};function n(i,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="prd-030-·-explore-v2-—-the-known-universe" tabindex="-1">PRD-030 · /explore v2 — The Known Universe <a class="header-anchor" href="#prd-030-·-explore-v2-—-the-known-universe" aria-label="Permalink to &quot;PRD-030 · /explore v2 — The Known Universe&quot;">​</a></h1><blockquote><p>Status · Draft (epic kickoff) · <strong>2026-07</strong> Owner · Marko Builds on · PRD-002 (/explore solar system, v1) · the Deep-Sky gallery · /science overlay pipeline · $lib/astronomy (from PRD-019 AR sky-pointing) Closes into · RFC-032 (context/scale-shell + scalable render architecture) May spawn · an ADR to lock the context-graph + object-catalog schema once the shape settles</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> This turns /explore from a solar-system viewer into a navigable model of the <em>known universe</em> — a product-shape decision touching the core 3D route, the data model, the render engine, /science, and the deep-sky gallery, staged across many slices over months. It needs an agreed frame — what we model, how we navigate it, how far it scales, and what stays honest — before any code lands. The current /explore (v1) is untouched; this is the zoom-<em>out</em> that wraps it.</p></blockquote><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Today /explore stops at the edge of the solar system, and the starfield beyond is decorative. Yet the product&#39;s whole thesis is &quot;learn about space&quot; — and the most humbling lesson is <em>context</em>: the Sun is one ordinary star, our galaxy one of billions, and the nebulae in our Deep-Sky gallery are real places with real positions. We have curated beautiful deep-sky imagery but no way to answer &quot;where is that, and what is around it?&quot; We want people to zoom out from home and <em>discover</em> the rest — scientifically grounded, honestly labeled, and beautiful.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p><strong>One <code>/explore</code>, a stack of nested contexts.</strong> Solar system at the bottom (v1, unchanged); pull back past the Oort cloud and the Sun collapses into the <em>real</em> nearby-star field; keep going through the Milky Way, the Local Group, and outward as data allows. You <strong>zoom within</strong> a context and <strong>warp between</strong> them. Every object is real (or an honestly-labeled model), every claim cited, every &quot;artist&#39;s impression&quot; badged as such.</p><h2 id="principles-non-negotiable" tabindex="-1">Principles (non-negotiable) <a class="header-anchor" href="#principles-non-negotiable" aria-label="Permalink to &quot;Principles (non-negotiable)&quot;">​</a></h2><ol><li><strong>v1 is sacred.</strong> The solar-system experience does not change or regress; v2 machinery loads lazily only when you cross the boundary outward.</li><li><strong>Honesty over spectacle.</strong> The <em>known/cataloged</em> universe, not &quot;the universe.&quot; Real / model / artistic always labeled; distances shown with real uncertainty; no fake to-scale galaxy renders (schematic maps instead, labeled).</li><li><strong>Curated, not dumped.</strong> Quality jewels with stories, not a billion-star tech demo (mirrors the Deep-Sky taste profile).</li><li><strong>Scalable by construction.</strong> Same render vocabulary + a device budget from slice 0 → runs on desktop and mobile, and keeps working as we add contexts outward.</li><li><strong>Reuse the spine.</strong> Keplerian engine (exoplanet systems), Panel (tactical detail), /science pipeline, Science-Lens pattern, provenance, i18n — all carry over.</li></ol><h2 id="pillars" tabindex="-1">Pillars <a class="header-anchor" href="#pillars" aria-label="Permalink to &quot;Pillars&quot;">​</a></h2><ul><li><strong>Exoplanet mini-orreries (the beachhead)</strong> — curated hero systems with real orbits reusing the Keplerian engine + full tactical panels.</li><li><strong>Navigable deep-sky</strong> — every gallery image gets a real position → &quot;fly me there&quot;; the placard and the 3D object become one.</li><li><strong>Culture doors</strong> — story as the way in: Vega→Contact, Gargantua→Interstellar, Kepler-16b→Tatooine, plus real message objects (Voyager, Arecibo, ‘Oumuamua). Fiction badged over fact.</li><li><strong>Black holes done right</strong> — M87*, Sagittarius A*, Cygnus X-1, Gargantua; real gravitational-lensing shader.</li><li><strong>Physics lenses</strong> — beyond a 3D map: curvature (spacetime embedding), time (dilation), causality (light-cones), and property-space (a flyable Hertzsprung-Russell diagram).</li><li><strong>Scientific honesty</strong> — the labeling + provenance discipline above.</li></ul><h2 id="the-geography-contexts-added-outward" tabindex="-1">The geography (contexts, added outward) <a class="header-anchor" href="#the-geography-contexts-added-outward" aria-label="Permalink to &quot;The geography (contexts, added outward)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Context</th><th>Scale</th><th>Content</th><th>Data</th><th>Nav</th></tr></thead><tbody><tr><td>Solar System (v1)</td><td>AU</td><td>unchanged</td><td>existing</td><td>zoom</td></tr><tr><td>Stellar Neighborhood</td><td>~100 ly</td><td>real nearby stars + exoplanet systems</td><td>HYG (~120k), NASA Exoplanet Archive</td><td>zoom</td></tr><tr><td>Milky Way</td><td>~100k ly</td><td>labeled spiral model, our position, Sag A*</td><td>spiral-arm model, Messier/OpenNGC</td><td>warp</td></tr><tr><td>Local Group</td><td>~10M ly</td><td>Andromeda, Magellanic Clouds, ~80 dwarfs</td><td>Local Group catalogs</td><td>warp</td></tr><tr><td>…beyond</td><td>—</td><td>cosmic web (deferred)</td><td>SDSS / future</td><td>warp</td></tr></tbody></table><h2 id="slice-roadmap-one-direction-full-detail-architecture-in-rfc-032" tabindex="-1">Slice roadmap (one direction; full detail + architecture in RFC-032) <a class="header-anchor" href="#slice-roadmap-one-direction-full-detail-architecture-in-rfc-032" aria-label="Permalink to &quot;Slice roadmap (one direction; full detail + architecture in RFC-032)&quot;">​</a></h2><ul><li><strong>Phase A — spine + first reveal.</strong> S0 boundary crossing (context engine, point renderer, device budget, the Sun→dot handoff); S1 stars become objects (select, panel, named stars, constellations, minimap, <code>?goto=</code>).</li><li><strong>Phase B — exoplanet beachhead.</strong> S2 exoplanet mini-orreries (real orbits, warp star→system); S3 exoplanet /science wing + culture layer v1.</li><li><strong>Phase C — the sky fills in.</strong> S4 deep-sky + gallery integration; S5 Milky Way context.</li><li><strong>Phase D — physics beyond the map.</strong> S6 black holes + curvature/time lenses; S7 property-space lenses.</li><li><strong>Phase E — and beyond.</strong> S8+ Local Group + message objects + narrated grand tour.</li></ul><h2 id="decisions-locked-at-kickoff-2026-07" tabindex="-1">Decisions locked at kickoff (2026-07) <a class="header-anchor" href="#decisions-locked-at-kickoff-2026-07" aria-label="Permalink to &quot;Decisions locked at kickoff (2026-07)&quot;">​</a></h2><ol><li><strong>Continuous zoom reaches the Stellar Neighborhood</strong> (the emotional first reveal is one continuous space); warp is reserved for galaxy-scale and beyond.</li><li><strong>Curated exoplanet hero set ≈ 25–30</strong> jewels, taste-profiled like the deep-sky gallery.</li><li><strong>v2.0 (first shippable) = slices 0–3</strong> (neighborhood + exoplanet beachhead + science/culture); Milky Way + physics lenses are v2.1/2.2.</li><li><strong>Culture layer ships as an optional overlay first</strong> (promote to a first-class browse mode later if it lands).</li><li><strong>Mobile = graceful tiers via the device budget</strong>; the core journey works everywhere, the heaviest lenses/shaders may be desktop-first.</li><li><strong>Working name: &quot;The Known Universe.&quot;</strong></li></ol><h2 id="success-criteria" tabindex="-1">Success criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success criteria&quot;">​</a></h2><ul><li>Zooming out of the solar system reveals the real nearby stars at their true positions/colors, at ≥30 fps on a mid-tier phone (budget-scaled).</li><li>A learner can find TRAPPIST-1 (wander or <code>?goto=</code>), warp in, and read a scientifically-backed panel on each planet.</li><li>Every deep-sky gallery image is reachable in 3D and vice-versa.</li><li>Nothing in v1 changes or regresses.</li></ul><h2 id="non-goals-this-epic" tabindex="-1">Non-goals (this epic) <a class="header-anchor" href="#non-goals-this-epic" aria-label="Permalink to &quot;Non-goals (this epic)&quot;">​</a></h2><p>Full Gaia billion-star render · real-time cosmology/simulation · AR/VR of the universe (explore-only) · fake to-scale galaxy distances · textured exoplanet surfaces (unknown) · user accounts / saved collections.</p><h2 id="tracking" tabindex="-1">Tracking <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;Tracking&quot;">​</a></h2><p>Epic tracked under a GH issue (TBD — to create at kickoff); slices land as sub-issues. Architecture + per-slice contracts in <strong>RFC-032</strong>. TA.md §explore gains a v2 subsystem entry as slices ship (not before).</p>',23)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
